// RiteKit hashtag-suggestions returns tags under data/result; read defensively.
const r = items[0].json || {};
const pool = r.data || r.result || r.tags || r;
let tags = [];
if (Array.isArray(pool)) tags = pool;
else if (pool && Array.isArray(pool.tags)) tags = pool.tags;
else if (pool && Array.isArray(pool.hashtags)) tags = pool.hashtags;
const names = tags.map(t => (typeof t === 'string' ? t : (t.tag || t.hashtag || t.name || ''))).filter(Boolean).slice(0, 8);
const hashtags = names.map(n => (n.startsWith('#') ? n : '#' + n)).join(' ');
return [{ json: { ...items[0].json, hashtags, hashtag_list: names } }];

